using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;
using WhatsBiz.Application.Common.Interfaces;
using WhatsBiz.Application.Features.Authentication.DTOs;
using WhatsBiz.Infrastructure.Persistence;
namespace WhatsBiz.Infrastructure.Identity; public sealed class AuthenticationService(UserManager<ApplicationUser> userManager, RoleManager<ApplicationRole> roleManager, ApplicationDbContext dbContext, IOptions<JwtOptions> options, JwtTokenGenerator jwtTokenGenerator) : IAuthenticationService { private readonly JwtOptions settings = options.Value; public async Task<AuthResponse> LoginAsync(LoginRequest request, CancellationToken token) { var user = await userManager.FindByNameAsync(request.Username); if (user is null || !user.IsActive || user.IsDeleted || !await userManager.CheckPasswordAsync(user, request.Password)) { await LogLogin(request.Username, null, false, "Invalid credentials", token); throw new UnauthorizedAccessException("Invalid username or password."); } await LogLogin(user.UserName ?? request.Username, user.Id, true, null, token); return await IssueAsync(user, null, token); } public async Task<AuthResponse> RefreshAsync(string refreshToken, CancellationToken token) { var stored = await dbContext.RefreshTokens.SingleOrDefaultAsync(x => x.TokenHash == Hash(refreshToken), token) ?? throw new UnauthorizedAccessException("Invalid refresh token."); if (!stored.IsActive || stored.IsDeleted || stored.RevokedOn is not null || stored.ExpiresOn <= DateTimeOffset.UtcNow) throw new UnauthorizedAccessException("Invalid refresh token."); var user = await userManager.FindByIdAsync(stored.UserId.ToString()) ?? throw new UnauthorizedAccessException("Invalid refresh token."); if (!user.IsActive || user.IsDeleted) throw new UnauthorizedAccessException("Invalid refresh token."); stored.RevokedOn = DateTimeOffset.UtcNow; stored.ModifiedOn = stored.RevokedOn; stored.ModifiedBy = user.UserName; stored.IsActive = false; return await IssueAsync(user, stored, token); } public async Task LogoutAsync(string refreshToken, CancellationToken token) { var stored = await dbContext.RefreshTokens.SingleOrDefaultAsync(x => x.TokenHash == Hash(refreshToken), token); if (stored is not null && stored.RevokedOn is null) { stored.RevokedOn = DateTimeOffset.UtcNow; stored.IsActive = false; await dbContext.SaveChangesAsync(token); var user = await userManager.FindByIdAsync(stored.UserId.ToString()); await dbContext.Database.ExecuteSqlInterpolatedAsync($"UPDATE TOP(1) admin.LoginHistory SET LogoutOn=SYSDATETIMEOFFSET() WHERE UserName={user!.UserName} AND LogoutOn IS NULL", token); } } private async Task<AuthResponse> IssueAsync(ApplicationUser user, RefreshToken? replaced, CancellationToken token) { var roles = (await userManager.GetRolesAsync(user)).ToArray(); var permissions = new HashSet<string>(StringComparer.Ordinal); foreach (var roleName in roles) { var role = await roleManager.FindByNameAsync(roleName); if (role is not null) foreach (var claim in await roleManager.GetClaimsAsync(role)) if (claim.Type == CustomClaimTypes.Permission) permissions.Add(claim.Value); } var (accessToken, expires) = jwtTokenGenerator.Generate(user, roles, permissions); var raw = Convert.ToBase64String(RandomNumberGenerator.GetBytes(64)); var refresh = new RefreshToken { UserId = user.Id, TokenHash = Hash(raw), ExpiresOn = DateTimeOffset.UtcNow.AddDays(settings.RefreshTokenExpiryDays), CreatedBy = user.UserName }; if (replaced is not null) replaced.ReplacedByTokenHash = refresh.TokenHash; dbContext.RefreshTokens.Add(refresh); await dbContext.SaveChangesAsync(token); return new(accessToken, raw, expires, new(user.Id, user.UserName ?? string.Empty, user.Email ?? string.Empty, roles, permissions.ToArray())); } private Task LogLogin(string userName, Guid? userId, bool succeeded, string? reason, CancellationToken token) => dbContext.Database.ExecuteSqlInterpolatedAsync($"INSERT admin.LoginHistory(UserId,UserName,Succeeded,FailureReason) VALUES({userId},{userName},{succeeded},{reason})", token); private static string Hash(string value) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))); }
